-- The Vacuum Wasp R.C.C., Rifts Dimension Book 2: Phase World p.92-93.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/add-vacuum-wasp-class.sql
--
-- Generated by scripts/class-check.mjs --emit-script from a validated draft.
-- Apostrophes are doubled and non-ASCII is spliced with char(); CR is stripped.
-- Run class-check on THIS file before applying - the ASCII/CRLF pre-flight only
-- fires against the real artifact.


-- The class itself. INSERT ... WHERE NOT EXISTS rather than INSERT OR IGNORE,
-- so re-running the script is a no-op instead of a silent partial write.
INSERT INTO imported_classes (class_id, name, system, markdown, status, created_by)
SELECT 'vacuum-wasp', 'Vacuum Wasp', 'rifts', '---
id: vacuum-wasp
name: Vacuum Wasp
system: rifts
category: rcc
source_book: Rifts Dimension Book 2: Phase World p.92-93
attribute_dice:
  IQ: "3d6"
  ME: "3d6"
  MA: "4d6"
  PS: "3d6+10"
  PP: "3d6+6"
  PE: "3d6+6"
  PB: "2d4"
  Spd: "6d6"
mdc_base: "1d4x100"
ppe_base: "3d6"
bonuses:
  combat: { attacks_base: 4, initiative: 3, strike: 3, parry: 3, dodge: 3, roll: 2, pull_punch: 2 }
  saves: { spell_magic: 2, horror_factor: 6 }
  at_level:
    - { level: 3, combat: { attacks: 1, parry: 1, dodge: 1 } }
    - { level: 4, combat: { strike: 1 } }
    - { level: 6, combat: { parry: 1, dodge: 1 } }
    - { level: 7, combat: { attacks: 1, strike: 1 } }
    - { level: 9, combat: { parry: 1, dodge: 1 } }
    - { level: 10, combat: { attacks: 1 } }
    - { level: 12, combat: { strike: 1 } }
psionics:
  isp_base: "3d6x10 plus 10 per level"
  powers: ["See Aura", "See The Invisible", "Sense Magic", "Mind Block Auto-Defense", "Telepathy"]
natural_abilities:
  - { name: "Multi-Spectrum Vision", description: "Sight equal to a cybernetic multi-optics eye, and radar, out to 2000 feet (610 m)." }
  - { name: "Regeneration", description: "Regrows lost limbs and heals 1d4x10 M.D.C. per eight hour rest period." }
  - { name: "Hive Recognition", description: "Psionically recognises members of its own hive, and attacks all others." }
  - { name: "Supersonic Flight", description: "Mach 6 in an atmosphere, Mach 10 in space. Flying is worth a further +2 to dodge, for a total of +5, and the wasp is +2 to engage in dogfighting; both are conditions the sheet has no field for and neither is in the stored bonuses. The Spd of 6d6 is the running speed." }
  - { name: "Bio-Electric Blast", description: "Generates electricity and fires it: 3d6 M.D. at level one, plus 1d6 per additional level of experience. Range 4000 feet (1200 m)." }
  - { name: "Free-Will Telepathy", description: "Telepathy costs the wasp no I.S.P. at all, and works only between members of its hive. A wasp that has broken from its hive keeps the power and has nobody left to use it on." }
  - { name: "Horror Factor", description: "10. A number the wasp projects, which the sheet has no field for." }
  - { name: "Size and Weight", description: "12 feet (3.6 m) tall and 2000 lbs (907 kg)." }
  - { name: "Average Life Span", description: "100 years." }
side_effects: "DOUBLE DAMAGE FROM PSIONIC ATTACKS. Every hive-spawn takes it, and there is no field on the sheet that halves or doubles incoming damage by type, so this is prose the G.M. applies. The other standing cost is not mechanical at all: a free wasp is persecuted almost everywhere in the Three Galaxies, and finds shelter mainly among outlaws, spacers, pirates and adventurers."
skills:
  occ_skills:
    - { choose: 2, from: ["Language: Other"], bonus: 5, note: "Two Languages of Choice (+5%). The catalog''s repeatable Language: Other row is what an any-language pick resolves through." }
    - { name: "Navigation: Stellar", bonus: 5, note: "Printed as Navigation: Space (+5%). The catalog files this book''s Navigation - Space of printed 151 as Navigation: Stellar; the row was re-cited onto this book in the skills batch." }
    - { choose: 1, categories: ["Pilot"], bonus: 10, note: "Piloting: One of Choice (+10%)." }
    - { name: "Weapon Systems", bonus: 5, note: "+5% bonus over base." }
    - { choose: 1, categories: ["Weapon Proficiencies"], note: "W.P.: One of Choice." }
  occ_related_skills:
    count: 8
    categories:
      - "Communications"
      - "Domestic"
      - { name: "Medical", only: ["First Aid"] }
      - { name: "Physical", only: ["Swimming", "Climbing"] }
      - { name: "Pilot", bonus: 5 }
      - { name: "Pilot Related", bonus: 5 }
      - { name: "Rogue", only: ["Prowl"], bonus: 5 }
      - { name: "Science", only: ["Mathematics: Basic", "Mathematics: Advanced"] }
      - { name: "Technical", bonus: 5 }
      - "Weapon Proficiencies"
      - "Wilderness"
    schedule: [{ level: 3, count: 1 }, { level: 5, count: 1 }, { level: 7, count: 1 }, { level: 10, count: 1 }, { level: 12, count: 1 }]
    note: "Eight at creation and one more at levels three, five, seven, ten and twelve. W.P. is printed Any EXCEPT hand to hand skills and boxing, and that exclusion is already enforced from the other side - all five hand to hand skills and Boxing are Physical skills, and Physical here is Swimming and Climbing only. Electrical, Espionage, Mechanical and Military are printed None and are omitted rather than listed."
  secondary_skills:
    count: 6
    note: "Six secondary skills from the same lists, at the base skill level and without the bonuses in parentheses."
extraction_notes: |
  - Read from the OCR cache of a scan and verified against 200 dpi renders of
    printed 92 and 93. The entry starts halfway down the left column of printed
    92, under the Killer Beetles'' last line, and ends on printed 93 at Secondary
    Skills with the Termite Engineers heading below it. Both pages were read in
    full because this chapter INTERLEAVES playable entries with NPC ones: the
    top of printed 92 is the Killer Beetles'' stat block, an entry the book marks
    NPC Villains, and it carries its own R.C.C. Skills line in the same column
    the wasp''s lore starts in.
  - NOTHING ON PRINTED 88-95 CARRIES A `Money:` OR A `Standard Equipment:` LINE.
    Grepped across the whole Star Hives chapter rather than inferred from the
    two pages this class needs. That is the shape of error this batch was
    watched for - the neighbouring entry here is an NPC that must not be
    imported at all - and the book simply gives none of these races money or
    gear. Both come from the O.C.C. if one is taken.
  - THE ABILITY TEXT STAYS INSIDE THIS ENTRY''S OWN COLUMN. A first draft of the
    Hive Recognition ability read "including hive-spawn of any OTHER hive",
    which is the KILLER BEETLES'' wording from printed 91, not the wasp''s. The
    wasp''s own line says only that it attacks all others. The elaboration was
    true and it came from the neighbouring entry, which is the exact bleed this
    chapter''s interleaving invites; caught by the reconcile pass and removed.
  - THE SENTIENT I.Q. IS THE ONE STORED. The book prints "I.Q. 2D6 (3D6)" and
    says the parenthetical is for sentient vacuum wasps. A player character IS
    the sentient kind: the book''s own skill line reads that normal wasps have no
    skills at all and only sentient ones may take the list below it, so
    importing 2d6 alongside that skill list would be describing two different
    creatures. 3d6 is stored and the hive-controlled 2d6 is recorded here.
  - `psionics.type` IS NOT SET, BECAUSE THE BOOK DOES NOT SET IT. The entry
    lists five powers and an I.S.P. pool and never says minor, major or master.
    An invented tier would change the psionic save target and would read as the
    book''s; an absent one reads as absent. Contrast the Pleasurer in this same
    batch, which the book calls a major psionic outright.
  - THE FLYING DODGE AND THE DOGFIGHTING BONUS ARE NOT STORED. The bonus line is
    "+3 to parry and dodge, +2 to dodge while flying (total +5 to dodge)": the
    +2 is conditional and `bonuses` is applied unconditionally, so storing +5
    would give a grounded wasp a dodge it has not got. `dogfighting` is worse
    than conditional - COMBAT_FIELDS in sheet.js is a literal list of nineteen
    keys and there is no dogfighting row, so `combat: { dogfighting: 2 }` would
    parse, validate and render NOWHERE. That is BOOK-INGEST-AUDIT.md F7''s shape
    exactly. Both are in the Supersonic Flight ability instead.
  - THE BONUS LINE DOES NOT DOUBLE-COUNT. It closes "All these are in addition
    to attribute bonuses", so derive.js adding its own P.P. figure on top is
    right rather than a second helping - the opposite of the Naruni Repo-Bot,
    whose line is headed "Includes P.P. bonuses". Read the heading, not the
    numbers.
  - FOUR ATTACKS ARE `attacks_base`, NOT A BONUS. The book states the count
    rather than adding to one, and the wasp cannot buy hand to hand at all -
    "hand to hand combat skills as used by humans are not applicable" - so
    `attacks_base: 4` replacing the default two is the whole of it. The three
    later attacks and the strike, parry and dodge progressions are in
    `bonuses.at_level`.
  - ROGUE: PROWL ONLY IS A CROSS-CATEGORY GRANT AND ITS +5% DOES NOT LAND. The
    catalog files Prowl under Physical, and `categoryAllows` admits a
    cross-category `only` because the class also lists Physical, so the skill is
    reachable. `categoryBonus` deliberately keys on the skill''s REAL category,
    so the +5% printed beside Rogue is not applied to it. The category label
    still shows the player "Rogue (Prowl only; +5%)", which is what the book
    prints. Recorded rather than worked around: moving Prowl into the Physical
    entry would hand Swimming and Climbing a bonus the book never gave them.
  - A CATEGORY PRINTED `None` IS AN EXCLUSION. Electrical, Espionage, Mechanical
    and Military are printed None and are omitted from `categories` entirely.
  - A RACE CARRIES NO xp_table. Printed 183 heads the column "Machine People &
    Phantom / Vacuum Wasps"; composition is race-primary, so a table here would
    win over the occupation''s and silently drop it. The ladder is: 0, 2,301,
    4,501, 10,001, 20,001, 30,001, 42,001, 65,001, 85,001, 110,001, 160,001,
    210,001, 285,001, 370,001, 450,001. Re-read this session off a 250 dpi
    render of printed 183 and it agrees band for band with the copies the
    Machine People (#411) and the Phantom (#415) recorded.
  - A natural M.D.C. creature, so there is no S.D.C., no hit points and no
    CORE_SDC_BY_CLASS entry.
  - Related and secondary skills come from the O.C.C. in the general case, but
    this race prints its own lists of both, so both are stored.
---

## Lore

A vacuum wasp is a living fighter craft. Twelve feet of armoured insect that
flies at Mach 6 in air and Mach 10 in vacuum and fires electricity, they are what
a Star Hive throws at anything it decides is dangerous or edible. They swarm out,
close, and try to breach the hull, and once inside they go for the bridge or the
engine room, because that is where a ship dies fastest.

They are not mindless. Under hive control they use feints and tactics, and they
press an attack heedless of their own losses until every one of them is dead.

## The ones who broke free

A few wasps have become self-aware and walked away from their hives, which is the
only reason there is a class here at all. The book files this entry as an
Optional Player Character and printed 183 gives it a share of a real experience
ladder, so the game means it.

Free wasps are not welcome anywhere. Most of the Three Galaxies shoots hive-spawn
on sight and asks afterwards, and a sentient wasp mostly finds shelter among
outlaws, spacers, pirates and adventurers - people with their own reasons not to
call the authorities.

Available as a player character with the Game Master''s approval. Alignment: any;
a wasp still under the control of a hive is usually aberrant or diabolic.

## GM Notes

The free-willed ones cannot remember being controlled. That is the standing
mystery of the hive-spawn - whether they are monsters or slaves - and a wasp
player character is the closest thing to a witness anybody has, and no help at
all.
', 'published', 'data-script'
WHERE NOT EXISTS (SELECT 1 FROM imported_classes WHERE class_id = 'vacuum-wasp');


-- Read the result back rather than trusting the exit code. d1-apply prints
-- these, and a CR in the stored markdown means the checkout mangled the file.
SELECT class_id, name, status, length(markdown) AS bytes, instr(markdown, char(13)) > 0 AS has_cr
  FROM imported_classes WHERE class_id = 'vacuum-wasp';

-- Records this run. REQUIRED: the smoke test fails a data script that has no
-- footer, or whose footer names a different file.
INSERT INTO data_script_runs (filename) VALUES ('add-vacuum-wasp-class.sql');
